internal static class BeschlussExtensions
{
    public static Beschluss ToDto(this BeschlussModel model)
    {
        return new(
            Id: model.Id,
            Beschlussnummer: model.Beschlussnummer,
            Beschlussdatum: model.Beschlussdatum,
            Erlaeuterungstext: model.Erlaeuterungstext,
            Link: model.Link,
            Vorgaenge: model.Vorgaenge.Select(x => x.ToFormDTO()).ToList(),
            IsImported: model.IsImported
        );
    }

    public static BeschlussModel ToModel(this Beschluss dto)
    {
        return new()
        {
            Id = dto.Id,
            Beschlussnummer = dto.Beschlussnummer,
            Beschlussdatum = dto.Beschlussdatum,
            Erlaeuterungstext = dto.Erlaeuterungstext,
            Link = dto.Link,
            Vorgaenge = dto.Vorgaenge.Select(x => x.ToModel()).ToList()
        };
    }
